// AGENTE 1 VIRAL: GUIONISTA MAESTRO CON TÉCNICAS VIRALES DE YOUTUBE
// Cuádruple Expertise: SEO + Teología + Copywriting + YouTube Viral
//
// Técnicas implementadas:
// - 3 tipos de hooks (Direct, Controversy, Negative)
// - Framework Hook-Shock-Validate-Tease
// - Open loops e information gaps

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// Ejecutar el agente maestro
try {
  const scriptPath = '/home/suario/ruy-projects/project-yt/agents/agent-1-viral-scriptwriter.js';
  const output = execSync(`node ${scriptPath}`, { 
    encoding: 'utf-8',
    cwd: '/home/suario/ruy-projects/project-yt'
  });

  // Buscar el archivo JSON generado más reciente
  const scriptsDir = '/home/suario/ruy-projects/project-yt/output/scripts';
  const files = fs.readdirSync(scriptsDir)
    .filter(f => f.startsWith('script-') && f.endsWith('.json'))
    .map(f => ({
      name: f,
      time: fs.statSync(path.join(scriptsDir, f)).mtime.getTime()
    }))
    .sort((a, b) => b.time - a.time);

  if (files.length === 0) {
    throw new Error('No se generó ningún guión');
  }

  // Leer el guión más reciente
  const latestScript = files[0].name;
  const scriptContent = JSON.parse(
    fs.readFileSync(path.join(scriptsDir, latestScript), 'utf-8')
  );

  return {
    success: true,
    scriptFile: latestScript,
    scriptData: scriptContent,
    verse: scriptContent.metadata.verse,
    category: scriptContent.metadata.category,
    output: output
  };

} catch (error) {
  return { 
    success: false, 
    error: error.message,
    stack: error.stack
  };
}

